const TZ = 'Europe/Warsaw';
const STALE = 8 * 60;
const MAX_FEED = 16 * 1024 * 1024;
const TRIPS = Object.freeze({early:'Warszawa Wschodnia', morning:'Warszawa Centralna', afternoon:'Warszawa Wschodnia', evening:'Warszawa Wschodnia'});
const ORIGIN = 'Данные: PKP PLK / Mikołaj Kuranowski (CC BY 4.0), обработаны TrainBoard.';
const ID_RE = /^PLK_LEO_[A-Z0-9_]{5,64}$/;

class Fault extends Error {
  constructor(code, retry = 0) { super(code); this.code = code; this.retry = retry; }
}
const safe = (e, fallback) => e instanceof Fault ? e.code : fallback;
const cleanClock = s => typeof s === 'string' && /^(?:[01][0-9]|2[0-3]):[0-5][0-9]$/.test(s) ? s : null;
const cleanTrack = s => /^(?:\d{1,4}[A-Za-z]?|[IVXLCDM]{1,8})$/.test(String(s??'').trim()) ? String(s).trim() : null;
let dateFormat,timeFormat;
function dayInWarsaw(ms) {
  dateFormat ??= new Intl.DateTimeFormat('sv-SE', {timeZone:TZ,year:'numeric',month:'2-digit',day:'2-digit'});
  return dateFormat.format(ms);
}
const clock = epoch => (timeFormat??=new Intl.DateTimeFormat('pl-PL', {timeZone:TZ,hour:'2-digit',minute:'2-digit',hourCycle:'h23'})).format(epoch*1000);
function plusMinute(hhmm, min) {
  const [h,m] = hhmm.split(':').map(Number);
  const t = ((60*h+m+min)%1440+1440)%1440;
  return `${String(Math.floor(t/60)).padStart(2,'0')}:${String(t%60).padStart(2,'0')}`;
}

function projectPlan(doc, day) {
  const sn = doc?.snapshot;
  if (doc?.fromStorage !== true || doc.requestedDate !== day || sn?.date !== day || !Array.isArray(sn.trains)) throw new Fault('plan-unavailable');
  // A covered but old plan can identify trips in the independently fresh live
  // feed. Never present its timetable/platform as a freshly confirmed fact.
  if (doc.status !== 'fresh' && !(doc.status === 'stale' && ['feed-old','check-overdue'].includes(doc.reason) && sn.coverageStart <= day && day <= sn.coverageEnd)) throw new Fault('plan-unavailable');
  const planTs=Math.floor(Date.parse(sn.checkedAt)/1000);
  if(!Number.isFinite(planTs)) throw new Fault('plan-incomplete');
  const entries = [];
  for (const [slot,station] of Object.entries(TRIPS)) {
    const candidates = sn.trains.filter(t=>t && t.slotId === slot && t.station === station && t.arrivalDate === day);
    if (candidates.length !== 1) throw new Fault('plan-incomplete');
    const t = candidates[0];
    if (!ID_RE.test(t.tripId ?? '') || !/^\d{2,8}$/.test(t.number ?? '') || !/^\d{4}-\d{2}-\d{2}$/.test(t.serviceDate ?? '') || !Number.isInteger(t.stopSequence) || t.stopSequence < 0) throw new Fault('plan-incomplete');
    const staticClock = cleanClock(t.scheduledTime) ?? (t.delayMinutes == null ? cleanClock(t.time) : null);
    entries.push({ slot, station, number: String(t.number), tripId:t.tripId, service:t.serviceDate.replaceAll('-',''), sequence:t.stopSequence,
      key:`${t.serviceDate}/${slot}/${t.number}`, planned:staticClock, planFresh:doc.status==='fresh', planTs,
      platform:cleanTrack(t.platform), track:cleanTrack(t.track) });
  }
  return entries;
}

// Select only matching protobuf entities. Skip by wire-length rather than decoding the whole network's stops.
function readFeed(bytes, entries) {
  if (!bytes.length || bytes.length > MAX_FEED) throw new Fault('feed-size');
  const wanted = Object.create(null), idLengths = new Set();
  for (const x of entries) {
    (wanted[x.tripId] ??= Object.create(null))[x.service] = x;
    idLengths.add(x.tripId.length);
  }
  const results = new Map(), all = new Set();
  const dec = new TextDecoder();
  let i = 0, timestamp = null, incremental = 0, entities = 0;
  const invalid = () => { throw new Fault('feed-invalid'); };
  function uv(end) {
    let v = 0;
    for (let k=0; k<10 && i<end; k++) {
      const b = bytes[i++];
      if (k<5) v |= (b&127) << (7*k);
      if (b<128) return v >>> 0;
    }
    return invalid();
  }
  function endAt(end) { const n = uv(end); return i+n <= end ? i+n : invalid(); }
  function skip(tag,end) {
    const wire = tag & 7;
    if (wire===0) uv(end);
    else if (wire===2) i=endAt(end);
    else if (wire===1 || wire===5) i+=wire===1 ? 8 : 4;
    else invalid();
    if (i>end) invalid();
  }
  function descriptor(end) {
    let id, datePos=-1, rel=0;
    while (i<end) {
      const tag=uv(end);
      if (tag===10 || tag===26) {
        const to=endAt(end);
        if (tag===10) {
          if (!idLengths.has(to-i) || bytes[i]!==80 || bytes[i+4]!==76 || bytes[i+5]!==69 || bytes[i+6]!==79) {i=end;return null;}
          id=dec.decode(bytes.subarray(i,to));
          if (!wanted[id]) {i=end;return null;}
        }
        if (tag===26 && to-i===8) datePos=i;
        i=to;
      } else if (tag===32) rel=uv(end);
      else skip(tag,end);
    }
    const x = id && datePos>=0 ? wanted[id]?.[dec.decode(bytes.subarray(datePos,datePos+8))] : null;
    return x ? {x,rel} : null;
  }
  function arrival(end) {
    let time=null, delay=null;
    while (i<end) {
      const tag=uv(end);
      if (tag===8) delay=uv(end)|0;
      else if (tag===16) time=uv(end);
      else skip(tag,end);
    }
    return {time,delay};
  }
  function stop(end) {
    let sequence=null, rel=0, value=null;
    while (i<end) {
      const tag=uv(end);
      if (tag===8) sequence=uv(end);
      else if (tag===18) value=arrival(endAt(end));
      else if (tag===40) rel=uv(end);
      else skip(tag,end);
    }
    return {sequence,rel,value};
  }
  function trip(end) {
    const start=i;
    let match=null;
    while (i<end) {
      const tag=uv(end);
      if (tag===10) { match=descriptor(endAt(end)); break; }
      skip(tag,end);
    }
    if (!match) { i=end; return; }
    const {x,rel}=match;
    if (all.has(x.key)) { results.delete(x.key); i=end; return; }
    all.add(x.key);
    if (rel===3 || rel===7) { results.set(x.key,{rel,stop:null,stamp:null}); i=end; return; }
    if (rel!==0) { i=end; return; }
    let found=null, stamp=null;
    i=start;
    while (i<end) {
      const tag=uv(end);
      if (tag===18) {
        const v=stop(endAt(end));
        if (v.sequence===x.sequence) found=v;
      } else if (tag===32) stamp=uv(end);
      else skip(tag,end);
    }
    if (found) results.set(x.key,{rel,stop:found,stamp});
  }
  function definitelyNotLeo(start,end) {
    // Common field order, validated against actual wire tags; other layouts use the general decoder.
    if(bytes[start]!==10 || bytes[start+1]>=128) return false;
    let p=start+2+bytes[start+1];
    if(p>=end || bytes[p++]!==26)return false;
    for(let n=0;n<4;n++) {
      if(p>=end)return false;
      if(bytes[p++]<128)break;
      if(n===3)return false;
    }
    if(p+12>=end || bytes[p]!==10 || bytes[p+1]>=128 || bytes[p+2]!==10 || bytes[p+3]<8 || bytes[p+3]+2>bytes[p+1]) return false;
    const s=p+4;
    if(bytes[s]!==80 || bytes[s+1]!==76 || bytes[s+2]!==75 || bytes[s+3]!==95)return false;
    return bytes[s+4]!==76 || bytes[s+5]!==69 || bytes[s+6]!==79 || bytes[s+7]!==95;
  }
  while (i<bytes.length) {
    const tag=uv(bytes.length);
    if (tag===10) {
      const h=endAt(bytes.length);
      while (i<h) {
        const f=uv(h);
        if (f===24) timestamp=uv(h);
        else if (f===16) incremental=uv(h);
        else skip(f,h);
      }
    } else if (tag===18) {
      const end=endAt(bytes.length);
      entities++;
      if(definitelyNotLeo(i,end)){i=end;continue;}
      while(i<end) {
        const f=uv(end);
        if (f===26) trip(endAt(end));
        else skip(f,end);
      }
    } else skip(tag,bytes.length);
  }
  if (!timestamp || incremental!==0 || !entities) invalid();
  return {timestamp,entities,results};
}

function observed(entry, update, nowSec) {
  const planned = entry.planned;
  const trustedPlan = entry.planFresh;
  if (update.rel===3 || update.rel===7) return {status:'cancelled',expected:null,delay:null,planned,trustedPlan};
  if (update.stamp && (nowSec-update.stamp > STALE || update.stamp-nowSec > 120)) return null;
  if (update.stop?.rel===1) return {status:'skipped',expected:null,delay:null,planned,trustedPlan};
  if (update.stop?.rel!==0 || !update.stop.value) return null;
  const {time,delay} = update.stop.value;
  const t = Number.isInteger(time) && Math.abs(time-nowSec)<36*3600 ? time : null;
  const d = Number.isInteger(delay) && Math.abs(delay)<24*3600 ? (Math.trunc((Math.abs(delay)+30)/60) * Math.sign(delay) || 0) : null;
  const expected = t!=null ? clock(t) : d!=null && planned && trustedPlan ? plusMinute(planned,d) : null;
  if (d==null && expected==null) return null;
  return {status:'scheduled',expected,delay:d,planned,trustedPlan};
}

function match(old, incoming) {
  // Unreported fields cannot remove a confirmed value or produce a false notification.
  const sameRun = old && old.status==='scheduled' && incoming.status==='scheduled';
  const merged = sameRun ? {...incoming,expected:incoming.expected??old.expected,delay:incoming.delay??old.delay} : incoming;
  if (!old) return {value:merged,change:null};
  const flags = { status:old.status!==incoming.status,
    delay:sameRun && incoming.delay!=null && incoming.delay!==old.delay,
    time:sameRun && incoming.expected!=null && incoming.expected!==old.expected,
    plan:sameRun && incoming.trustedPlan && old.trustedPlan && incoming.planned!=null && old.planned!=null && incoming.planned!==old.planned };
  return {value:merged,change:Object.values(flags).some(Boolean) ? flags : null};
}

function cardFor(entry, old, next, changes, sourceTs) {
  const fmt = d => d==null ? '—' : d===0 ? '0 мин' : `${d>0?'+':''}${d} мин`;
  let heading;
  if (next.status==='cancelled') heading = 'РЕЙС ОТМЕНЁН';
  else if (next.status==='skipped') heading = 'ПРОПУСК ОСТАНОВКИ';
  else if (changes.status) heading = 'РЕЙС ВОССТАНОВЛЕН';
  else if (changes.delay && next.delay===0 && old.delay!=null) heading = 'ЗАДЕРЖКА СНЯТА';
  else if (next.delay>0) heading = 'ЗАДЕРЖКА';
  else heading = 'ИЗМЕНЕНИЕ ПРИБЫТИЯ';
  const rows = [ [next.trustedPlan ? 'По расписанию' : 'Сохранённый план',changes.plan ? `${old.planned} → ${next.planned}` : next.planned??'—'],
    ['Ожидается',next.expected==null?'—':changes.time && old.expected ? `${old.expected} → ${next.expected}` : next.expected] ];
  if (changes.delay || next.delay!=null) rows.push(['Задержка',changes.delay && old.delay!=null ? `${fmt(old.delay)} → ${fmt(next.delay)}` : fmt(next.delay)]);
  return {heading,train:`Поезд: ${entry.number}`,station:entry.station,rows,
    footer:`Данные на ${clock(sourceTs)} по Варшаве`,caption:`${ORIGIN}\nПоток: ${new Date(sourceTs*1000).toISOString()}.`};
}

