function updatePlans(s,entries,now) {
  s.planLast??={};
  for(const e of entries) {
    if(!e.planFresh) continue;
    const old=s.planLast[e.slot];
    const next={number:e.number,planned:e.planned,platform:e.platform,track:e.track};
    // Missing information is not a confirmed change. Retain the last known value.
    if(old) for(const key of Object.keys(next)) if(next[key]===null) next[key]=old[key];
    s.planLast[e.slot]=next;
    if(!old) continue;
    const changed=Object.keys(next).filter(key=>next[key]!=null && next[key]!==old[key]);
    if(!changed.length) continue;
    const labels={number:'Номер поезда',planned:'По расписанию',platform:'План. перрон',track:'План. путь'};
    const name=changed.length===1&&changed[0]==='platform'?'ИЗМЕНЕНИЕ ПЕРРОНА В ПЛАНЕ':changed.length===1&&changed[0]==='track'?'ИЗМЕНЕНИЕ ПУТИ В ПЛАНЕ':'ИЗМЕНЕНИЕ ПЛАНА';
    const photo={heading:name,train:`Поезд: ${e.number}`,station:e.station,
      rows:changed.map(key=>[labels[key],`${old[key]??'—'} → ${next[key]}`]),
      footer:`План на ${clock(e.planTs)} по Варшаве`,caption:'Плановые данные TrainBoard. Не подтверждение фактического перрона или пути.'};
    const key=`plan/${e.slot}`;
    s.queue=s.queue.filter(q=>q.key!==key);
    s.queue.push({key,kind:'plan',photo,ts:now});
  }
}

function problemCard(planFailed,now) {
  return {heading:'ДАННЫЕ НЕДОСТУПНЫ',train:'TrainBoard',station:planFailed?'Плановое расписание':'Оперативный источник',
    rows:[['Источник','Недоступен'],['Данные','Не подтверждены']],footer:`Проверка в ${clock(now)} по Варшаве`,
    caption:'Свежие данные недоступны. Устаревшие сведения не выдаются за актуальные.'};
}

